    case 'DECREMENT':
      // return new state with count - 1
    default:
      return state
  }
}

exercises.answer:
function reducer(state, action) {
  switch (action.type) {
    case 'INCREMENT':
      return { ...state, count: state.count + 1 }
    case 'DECREMENT':
      return { ...state, count: state.count - 1 }
    default:
      return state
  }
}
